// mixedAssertStoreZeroOnError asserts Store returns the zero Value alongside any error.
func mixedAssertStoreZeroOnError(
	tb testing.TB,
	m Mixed,
	fx MixedFixture,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := m.Store(ctx, fx.Value())
	if err == nil {
		tb.Skip("Store answered for a cancelled context, so this check has no error to inspect")
	}

	var zero causal.Value
	if got != zero {
		tb.Errorf("Store must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

